class Visual final : public Scene {
  struct Star { float x, y, tw; };
  std::vector<Star> stars;
  float breath = 0, flash = 0;
  static float vhash(int x, int y) {
    uint32_t h = uint32_t(x) * 374761393u + uint32_t(y) * 668265263u;
    h = (h ^ (h >> 13)) * 1274126177u; h ^= h >> 16;
    return float(h & 0xffffu) / 65535.0f;
  }
  static float vnoise(float x, float y) {
    int xi = int(std::floor(x)), yi = int(std::floor(y));
    float xf = x - float(xi), yf = y - float(yi);
    float u = xf * xf * (3.0f - 2.0f * xf), v = yf * yf * (3.0f - 2.0f * yf);
    float a = vhash(xi, yi), b = vhash(xi + 1, yi);
    float c = vhash(xi, yi + 1), d = vhash(xi + 1, yi + 1);
    return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
  }
 public:
  void reset(uint32_t seed) override {
    Random rng(seed); stars.clear(); stars.reserve(110); breath = 0; flash = 0;
    for (int i = 0; i < 110; i++)
      stars.push_back({rng.unit(), rng.unit() * 0.62f, rng.unit() * 6.2831853f});
  }
  void update(const Frame& f) override {
    breath += (f.music.energy - breath) * float(1.0 - std::exp(-f.delta * 3.0));
    for (const auto& band : f.music.events)
      for (const auto& e : band) flash += e.strength;
    flash *= float(std::exp(-f.delta * 4.0));
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = float(f.time) * f.speed;
    float glow = (0.8f + 0.35f * breath + 0.5f * flash) * f.intensity;
    if (glow > 1.0f) glow = 1.0f; if (glow < 0.0f) glow = 0.0f;
    Paint sky = Paint::linear({0, 0}, {0, h},
      {Color::argb(0xff01030f), Color::argb(0xff04122b),
       Color::argb(0xff062033), Color::argb(0xff010409)}, {0, 0.45f, 0.8f, 1.0f});
    c.rect({0, 0, w, h}, sky);
    std::vector<Vec2> batch; batch.reserve(stars.size());
    for (const auto& s : stars) batch.push_back({s.x * w, s.y * h});
    Paint sp; sp.blend = Blend::plus;
    sp.color = {1, 1, 1, (0.35f + 0.25f * std::abs(std::sin(t * 0.9f))) * glow};
    c.points(batch, 0.8f, sp);
    const float cy[4] = {0.30f, 0.36f, 0.44f, 0.50f};
    const float am[4] = {0.05f, 0.06f, 0.045f, 0.035f};
    const float th[4] = {0.20f, 0.16f, 0.13f, 0.09f};
    const float sp2[4] = {0.18f, -0.25f, 0.33f, -0.40f};
    const float fr[4] = {1.7f, 2.3f, 3.1f, 4.2f};
    const uint32_t col[4] = {0xff38ffc4, 0xff4be0ff, 0xff9d6bff, 0xffff5fd2};
    for (int b = 0; b < 4; b++) {
      float amp = am[b] * (1.0f + 0.4f * breath);
      Path ribbon;
      for (int i = 0; i <= 26; i++) {
        float x = float(i) / 26.0f * w;
        float n = vnoise(float(i) * 0.22f + t * sp2[b], float(b) * 5.5f + t * 0.15f);
        float y = h * cy[b] + std::sin(float(i) * fr[b] * 0.14f + t * sp2[b] * 3.0f) * h * amp
          + (n - 0.5f) * h * 0.07f;
        if (i == 0) ribbon.moveTo(x, y); else ribbon.lineTo(x, y);
      }
      for (int i = 26; i >= 0; i--) {
        float x = float(i) / 26.0f * w;
        float n = vnoise(float(i) * 0.22f + t * sp2[b], float(b) * 5.5f + t * 0.15f);
        float y = h * cy[b] + std::sin(float(i) * fr[b] * 0.14f + t * sp2[b] * 3.0f) * h * amp
          + (n - 0.5f) * h * 0.07f + h * th[b] * (0.6f + n * 0.8f);
        ribbon.lineTo(x, y);
      }
      ribbon.close();
      Color base = Color::argb(col[b]);
      Paint band = Paint::linear({0, h * (cy[b] - amp - th[b])}, {0, h * (cy[b] + amp + 0.02f)},
        {{base.r, base.g, base.b, 0}, {base.r, base.g, base.b, 0.40f * glow},
         {base.r, base.g, base.b, 0}}, {0, 0.45f, 1.0f});
      band.blend = Blend::plus;
      c.path(ribbon, band);
    }
    Path ridge; ridge.moveTo(0, h);
    for (int i = 0; i < 42; i++)
      ridge.lineTo(float(i) / 41.0f * w,
        h * (0.8f + vnoise(float(i) * 0.35f, 3.0f) * 0.12f) - float(std::abs(i - 20)) * 0.8f);
    ridge.lineTo(w, h); ridge.close();
    Paint dk; dk.color = Color::argb(0xff01050c);
    c.path(ridge, dk);
  }
};

class Visual final : public Scene {
  static const int kTail = 5;
  int count = 0, done = 0;
  std::vector<float> x, y, life, trail;
  void step(float size_w, float size_h, float rate) {
    // El instante se deriva del contador de pasos, no del fotograma: a 30 y a
    // 60 FPS se aplica exactamente la misma secuencia de campos.
    float time = float(done) * (1.0f / 60.0f) * rate * 6.2831853f;
    for (int i = 0; i < count; i++) {
      if (life[i] <= 0.0f) {
        x[i] = hash11(float(i) * 1.37f + float(done) * 0.017f) * size_w;
        y[i] = hash11(float(i) * 2.71f + float(done) * 0.029f) * size_h;
        for (int k = 0; k < kTail; k++) {
          int o = (i * kTail + k) * 4;
          trail[o] = x[i]; trail[o + 1] = y[i];
          trail[o + 2] = x[i]; trail[o + 3] = y[i];
        }
        life[i] = 1.0f;
      }
      float px = x[i], py = y[i];
      float a = std::sin(px * 0.0031f + time * 0.16f) * 1.5f
        + std::cos(py * 0.0027f - time * 0.13f) * 1.5f
        + std::sin((px + py) * 0.0014f + time * 0.07f) * 1.1f;
      float vx = std::cos(a) * 1.5f, vy = std::sin(a) * 1.5f;
      // Remolino central: sustituye al dedo, con la música como energía.
      float dx = px - size_w * 0.5f, dy = py - size_h * 0.5f;
      float d2 = dx * dx + dy * dy;
      float radius2 = 15000.0f + 12000.0f * fenergy;
      if (d2 < radius2 && d2 > 1.0f) {
        float inv = 1.0f / std::sqrt(d2);
        float k = (1.0f - d2 / radius2) * 2.4f;
        vx += -dy * inv * k; vy += dx * inv * k;
      }
      float nx = px + vx, ny = py + vy;
      x[i] = nx; y[i] = ny;
      life[i] -= 0.0016f;
      int base = i * kTail * 4;
      for (int k = kTail - 1; k > 0; k--) {
        int o = base + k * 4;
        trail[o] = trail[o - 4]; trail[o + 1] = trail[o - 3];
        trail[o + 2] = nx; trail[o + 3] = ny;
      }
      trail[base] = px; trail[base + 1] = py;
      trail[base + 2] = nx; trail[base + 3] = ny;
      if (nx < -30.0f || nx > size_w + 30.0f || ny < -30.0f || ny > size_h + 30.0f)
        life[i] = 0.0f;
    }
    done++;
  }
  float fenergy = 0.0f;
  float lastw = 0.0f, lasth = 0.0f;
  static float hash11(float p) {
    float s = std::sin(p * 12.9898f) * 43758.5453f;
    return s - std::floor(s);
  }
 public:
  void reset(uint32_t seed) override {
    (void)seed;
    count = 1400; done = 0;
    x.assign(count, 0.0f); y.assign(count, 0.0f);
    life.assign(count, 0.0f);
    trail.assign(count * kTail * 4, 0.0f);
    lastw = 0.0f; lasth = 0.0f; fenergy = 0.0f;
  }
  void update(const Frame& f) override {
    if (f.width != lastw || f.height != lasth) {
      // Reconstruye la rejilla con el tamaño real: la escena se previsualiza
      // primero en miniatura y luego a pantalla completa.
      count = int(1400.0f * (0.5f + 0.5f * std::min(1.0f, std::max(0.0f, (f.detail - 0.25f) / 0.75f))));
      x.assign(count, 0.0f); y.assign(count, 0.0f);
      life.assign(count, 0.0f);
      trail.assign(count * kTail * 4, 0.0f);
      lastw = f.width; lasth = f.height; done = 0;
    }
    fenergy = f.music.energy;
    float rate = (f.reducedMotion ? 0.25f : 1.0f) * f.speed;
    int target = int(float(f.time) * rate * 60.0f + 0.001f);
    int guard = 0;
    while (done < target && guard < 16) { step(f.width, f.height, rate); guard++; }
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    Paint bg; bg.color = Color::argb(0xff05090c);
    c.rect({0, 0, w, h}, bg);
    const uint32_t cols[3] = {0xff3fd8a5, 0xffc6e84f, 0xff58c7f3};
    const float alphas[3] = {0.4f, 0.267f, 0.267f};
    int per = (count + 2) / 3;
    for (int b = 0; b < 3; b++) {
      Path p;
      // El cubo se reparte en indices de particula; base multiplica por
      // kTail * 4 para saltar a su bloque dentro del rastro.
      int from = b * per;
      int to = (b == 2) ? count : (b + 1) * per;
      for (int i = from; i < to; i++) {
        int base = i * kTail * 4;
        for (int k = 0; k < kTail; k++) {
          int o = base + k * 4;
          p.moveTo(trail[o], trail[o + 1]);
          p.lineTo(trail[o + 2], trail[o + 3]);
        }
      }
      Color cc = Color::argb(cols[b]);
      Paint q; q.blend = Blend::plus;
      q.color = {cc.r, cc.g, cc.b, std::min(1.0f, alphas[b] * f.intensity)};
      q.strokeWidth = 1.1f; q.strokeCap = 1; q.strokeJoin = 1;
      c.path(p, q);
    }
  }
};

class Visual final : public Scene {
  float smoothBass = 0.0f;
 public:
  void reset(uint32_t seed) override { (void)seed; smoothBass = 0.0f; }
  void update(const Frame& f) override {
    smoothBass += (f.music.bass - smoothBass) * float(1.0 - std::exp(-f.delta * 8.0));
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    c.material("plasma", {0, 0, w, h}, {float(f.time) * f.speed, smoothBass});
    Paint shade = Paint::radial({w * 0.5f, h * 0.5f}, h * 0.75f,
      {{0, 0, 0, 0}, {0, 0, 0, 0.6f}}, {0, 1.0f});
    c.rect({0, 0, w, h}, shade);
  }
};

