class Visual final : public Scene {
  static constexpr float kCell = 74.0f;
  struct Node { float x, y, vx, vy, r, phase; };
  std::vector<Node> nodes;
  std::vector<int> head, next;
  int cols = 1, rows = 1, done = 0;
  float lastw = 0, lasth = 0, lastDetail = -1.0f, pull = 0.0f;
  void build(int count, float w, float h) {
    nodes.clear(); nodes.reserve(count);
    Random rng(41);
    for (int i = 0; i < count; i++) {
      Node n;
      n.x = rng.unit() * w; n.y = rng.unit() * h;
      float a = rng.unit() * 6.2831853f;
      float sp = 8.0f + rng.unit() * 22.0f;
      n.vx = std::cos(a) * sp; n.vy = std::sin(a) * sp;
      n.r = 0.9f + rng.unit() * 2.2f;
      n.phase = rng.unit() * 6.2831853f;
      nodes.push_back(n);
    }
    cols = int(std::ceil(w / kCell)); if (cols < 1) cols = 1; if (cols > 512) cols = 512;
    rows = int(std::ceil(h / kCell)); if (rows < 1) rows = 1; if (rows > 1024) rows = 1024;
    head.assign(cols * rows, -1);
    next.assign(nodes.size(), -1);
    done = 0;
  }
  void step(float w, float h) {
    const float dt = 1.0f / 60.0f;
    float force = 12000.0f + pull * 14000.0f;
    float fx = w * 0.5f, fy = h * 0.5f;
    for (size_t i = 0; i < nodes.size(); i++) {
      Node& n = nodes[i];
      float dx = n.x - fx, dy = n.y - fy;
      float d2 = dx * dx + dy * dy;
      if (d2 < force && d2 > 4.0f) {
        float inv = 1.0f / std::sqrt(d2);
        float k = (1.0f - d2 / force) * 140.0f * dt * 8.0f;
        n.vx += dx * inv * k; n.vy += dy * inv * k;
      }
      n.x += n.vx * dt; n.y += n.vy * dt;
      n.vx *= 1.0f - dt * 0.55f; n.vy *= 1.0f - dt * 0.55f;
      if (n.x < 0) { n.x = 0; n.vx = -n.vx; }
      if (n.x > w) { n.x = w; n.vx = -n.vx; }
      if (n.y < 0) { n.y = 0; n.vy = -n.vy; }
      if (n.y > h) { n.y = h; n.vy = -n.vy; }
    }
    done++;
  }
 public:
  void reset(uint32_t seed) override {
    (void)seed;
    nodes.clear();
    // La rejilla arranca con una celda: render puede ejecutarse antes que el
    // primer update y nunca debe leer un vector vacío.
    cols = 1; rows = 1;
    head.assign(1, -1);
    next.assign(1, -1);
    lastw = 0; lasth = 0; lastDetail = -1.0f; done = 0; pull = 0.0f;
  }
  void update(const Frame& f) override {
    float density = std::min(1.0f, std::max(0.0f, (f.detail - 0.25f) / 1.75f));
    if (f.width != lastw || f.height != lasth || f.detail != lastDetail) {
      int count = int(190.0f * (0.6f + 0.4f * density));
      if (count < 24) count = 24;
      build(count, f.width, f.height);
      lastw = f.width; lasth = f.height; lastDetail = f.detail;
    }
    pull = f.music.energy;
    float rate = f.reducedMotion ? 0.2f : 1.0f;
    int target = int(float(f.time) * f.speed * rate * 60.0f + 0.001f);
    int guard = 0;
    while (done < target && guard < 16) { step(f.width, f.height); guard++; }
    // La rejilla se reconstruye aquí y no en render: render es const y el
    // vector de índices solo puede leerse desde él.
    std::fill(head.begin(), head.end(), -1);
    for (size_t i = 0; i < nodes.size(); i++) {
      int c0 = int(nodes[i].x / kCell);
      int r0 = int(nodes[i].y / kCell);
      if (c0 < 0) c0 = 0; if (c0 > cols - 1) c0 = cols - 1;
      if (r0 < 0) r0 = 0; if (r0 > rows - 1) r0 = rows - 1;
      int idx = r0 * cols + c0;
      next[i] = head[idx];
      head[idx] = int(i);
    }
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float boost = (0.8f + 0.4f * f.music.energy) * f.intensity;
    if (boost > 1.0f) boost = 1.0f; if (boost < 0.0f) boost = 0.0f;
    Paint bg = Paint::radial({w * 0.5f, h * 0.5f}, std::max(w, h) * 0.75f,
      {Color::argb(0xff120f24), Color::argb(0xff080710), Color::argb(0xff04040a)},
      {0.0f, 0.6f, 1.0f});
    c.rect({0, 0, w, h}, bg);

    // Sin nodos todavía: sólo el fondo. La rejilla se consulta ya construida.
    if (nodes.empty() || head.empty()) return;

    // Rejilla espacial construida en update: aquí sólo se consulta.
    // Aristas en cuatro cubos de alpha.
    Path buckets[4];
    const float cell2 = kCell * kCell;
    for (int r = 0; r < rows; r++) {
      for (int cc = 0; cc < cols; cc++) {
        for (int i = head[r * cols + cc]; i != -1; i = next[i]) {
          for (int dr = 0; dr <= 1; dr++) {
            for (int dc = (dr == 0 ? 0 : -1); dc <= 1; dc++) {
              int rr = r + dr, cx = cc + dc;
              if (rr < 0 || rr >= rows || cx < 0 || cx >= cols) continue;
              for (int j = head[rr * cols + cx]; j != -1; j = next[j]) {
                if (j <= i) continue;
                float ddx = nodes[i].x - nodes[j].x, ddy = nodes[i].y - nodes[j].y;
                float d2 = ddx * ddx + ddy * ddy;
                if (d2 > cell2) continue;
                int b = int((1.0f - d2 / cell2) * 3.99f);
                if (b < 0) b = 0; if (b > 3) b = 3;
                buckets[b].moveTo(nodes[i].x, nodes[i].y);
                buckets[b].lineTo(nodes[j].x, nodes[j].y);
              }
            }
          }
        }
      }
    }
    Paint line;
    line.strokeWidth = 0.8f; line.blend = Blend::plus;
    for (int b = 0; b < 4; b++) {
      line.color = {0.651f, 0.545f, 1, (0.08f + float(b) * 0.11f) * boost};
      c.path(buckets[b], line);
    }

    // Nodos: puntos agrupados, con un segundo lote más grande cerca del centro.
    std::vector<Vec2> dim, hot;
    dim.reserve(nodes.size()); hot.reserve(nodes.size());
    float fx = w * 0.5f, fy = h * 0.5f;
    for (const auto& n : nodes) {
      dim.push_back({n.x, n.y});
      float dx = n.x - fx, dy = n.y - fy;
      if (dx * dx + dy * dy < 36100.0f) hot.push_back({n.x, n.y});
    }
    Paint dp; dp.blend = Blend::plus;
    dp.color = {0.796f, 0.722f, 1, 0.55f * boost};
    c.points(dim, 1.1f, dp);
    if (!hot.empty()) {
      Paint hp; hp.blend = Blend::plus;
      hp.color = {0.651f, 0.545f, 1, 0.12f * boost};
      c.points(hot, 6.0f, hp);
    }
  }
};

class Visual final : public Scene {
 public:
  void reset(uint32_t seed) override { (void)seed; }
  void update(const Frame& f) override { (void)f; }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = float(f.time) * f.speed;
    float time = t * 6.2831853f;
    float energy = std::min(1.4f, f.music.energy * 1.6f + f.music.bass * 0.8f) * f.intensity;
    float cx = w * 0.5f, cy = h * 0.5f;
    float rad = std::min(w, h) * 0.24f;
    Paint bg = Paint::radial({cx, cy}, std::max(w, h) * 1.1f,
      {Color::argb(0xff1b0d05), Color::argb(0xff0a0608), Color::argb(0xff04040a)},
      {0.0f, 0.5f, 1.0f});
    c.rect({0, 0, w, h}, bg);

    // ── Filamentos de corona: un Path, 96 rayos ──
    Path rays;
    for (int i = 0; i < 96; i++) {
      float a = float(i) / 96.0f * 6.2831853f;
      float n = std::sin(a * 9.0f + time * 1.4f) * 0.5f + std::sin(a * 23.0f - time * 0.9f) * 0.5f;
      float len = rad * (1.25f + std::abs(n) * (1.5f + energy));
      rays.moveTo(cx + std::cos(a) * rad * 1.02f, cy + std::sin(a) * rad * 1.02f);
      rays.lineTo(cx + std::cos(a + 0.01f) * len, cy + std::sin(a + 0.01f) * len);
    }
    Paint add; add.blend = Blend::plus;
    add.color = {1, 0.416f, 0.333f, 0.102f};
    add.strokeWidth = 1.6f; add.strokeCap = 1; add.strokeJoin = 1;
    c.path(rays, add);

    // ── Halo en tres pasadas (bloom falso, sin saveLayer) ──
    for (int i = 3; i >= 1; i--) {
      Paint hp; hp.blend = Blend::plus;
      hp.color = {0.961f, 0.647f, 0.141f, 0.043f};
      c.circle({cx, cy}, rad * (1.0f + float(i) * 0.42f + energy * 0.1f), hp);
    }

    // ── limbo ──
    static const float harm[7][3] = {
      {5, 0.055f, 0.90f}, {8, 0.032f, -1.40f}, {13, 0.022f, 2.10f},
      {3, 0.048f, -0.60f}, {21, 0.012f, 3.00f}, {2, 0.050f, 0.45f},
      {34, 0.008f, -2.40f}};
    Path limb;
    const int steps = 128;
    for (int i = 0; i <= steps; i++) {
      float a = float(i) / float(steps) * 6.2831853f;
      float d = 1.0f;
      for (int k = 0; k < 7; k++)
        d += harm[k][1] * std::sin(a * harm[k][0] + time * harm[k][2]) * (1.0f + energy * 0.8f);
      float r = rad * d * (1.0f + std::sin(time * 2.2f) * 0.012f);
      float x = cx + std::cos(a) * r, y = cy + std::sin(a) * r;
      if (i == 0) limb.moveTo(x, y); else limb.lineTo(x, y);
    }
    limb.close();
    Paint limbPaint = Paint::radial({cx - rad * 0.25f, cy - rad * 0.3f}, rad * 1.3f,
      {Color::argb(0xfffff6d8), Color::argb(0xfff5a524),
       Color::argb(0xe6e8541f), Color::argb(0xe65a0a1e)},
      {0.0f, 0.35f, 0.78f, 1.0f});
    c.path(limb, limbPaint);

    // ── Gránulos de plasma recortados al limbo ──
    c.save();
    c.clip(limb);
    for (int i = 0; i < 26; i++) {
      float a = time * 0.35f + float(i) * 2.399f;
      float rr = rad * (0.25f + float((i * 37) % 70) / 100.0f);
      Paint gp;
      if (i % 3 == 0) gp.color = {1, 0.941f, 0.753f, 0.22f};
      else gp.color = {1, 0.353f, 0.157f, 0.188f};
      c.circle({cx + std::cos(a) * rr, cy + std::sin(a * 1.3f) * rr},
        rad * (0.10f + float(i % 5) * 0.035f), gp);
    }
    c.restore();
  }
};

class Visual final : public Scene {
  struct Blob { float radius, p1, p2, sx, sy; };
  std::vector<Blob> blobs;
  float energy = 0;
  float smoothBass = 0;
 public:
  void reset(uint32_t seed) override {
    Random rng(seed); blobs.clear(); energy = 0; smoothBass = 0;
    for (int i = 0; i < 7; i++)
      blobs.push_back({0.14f + rng.unit() * 0.13f,
        rng.unit() * 6.2831853f, rng.unit() * 6.2831853f,
        0.23f + float(i) * 0.045f, 0.19f + float(i) * 0.037f});
  }
  void update(const Frame& f) override {
    energy += (f.music.energy - energy) * float(1.0 - std::exp(-f.delta * 4.0));
    smoothBass += (f.music.bass - smoothBass) * float(1.0 - std::exp(-f.delta * 6.0));
  }
  void render(const Frame& f, Canvas& c) const override {
    float w = f.width, h = f.height;
    float t = float(f.time) * f.speed;
    Paint bg; bg.color = Color::argb(0xff03000c);
    c.rect({0, 0, w, h}, bg);
    std::vector<float> u;
    u.reserve(64);
    u.push_back(t);
    u.push_back(std::clamp(smoothBass, 0.0f, 1.0f));
    u.push_back(std::clamp(energy * f.intensity, 0.0f, 1.0f));
    u.push_back(f.glow);
    for (const auto& b : blobs) {
      u.push_back(w * (0.5f + std::sin(t * b.sx + b.p1) * 0.33f));
      u.push_back(h * (0.5f + std::sin(t * b.sy + b.p2) * 0.36f));
      u.push_back(b.radius * w * (1.0f + energy * 0.25f));
    }
    c.material("chrome", {0, 0, w, h}, u);
    Paint shade = Paint::radial({w * 0.5f, h * 0.5f}, std::max(w, h) * 0.75f,
      {{0, 0, 0, 0}, {0, 0, 0, 0.45f}}, {0.55f, 1.0f});
    c.rect({0, 0, w, h}, shade);
  }
};

